WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_eng_e_people'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '人数变化', 'kp-eng-e-people', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "人数变化型工程"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "人多力量大。每增加一个人，就是增加一份基础效率。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "题目中出现：“原有 10 名工人，开工 3 天后，又调来 5 名工人加入……”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心破题：单位人天法"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "不要去算每个人效率是多少，直接假设 【1名工人1天的效率为 1】。"}]}, {"type": "katexBlock", "attrs": {"content": "W_{总} = 初始人数 \\times 天数_1 + 变动后人数 \\times 天数_2"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[明确题目给出了具体的人数变动] --> B[令 1人1天 = 1 个单位工程量]\nB --> C[算出总量 W = 原定人数 × 原定天数]\nC --> D[根据时间轴, 算出变动前已经消耗的工程量]\nD --> E[用剩余工程量 ÷ 变动后的总人数 = 剩下需要的天数]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 修一段路，15 人原本需要 20 天。修了 5 天后，调走了 5 人。问剩下的路还需要几天修完？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "赋效率：设每人每天效率为 1。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算总量：W = 15 人 × 20 天 = 300。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "前半段：15 人修了 5 天，完成 = 15 × 5 = 75。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算剩余：W余 = 300 - 75 = 225。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "后半段：调走 5 人，还剩 10 人。剩下需要的天数 = 225 ÷ 10 = 22.5 天。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "混淆“调走”与“剩下”：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "题目说“调走 5 人”，很多人做除法时顺手除以了 5。一定要把“当前在场总人数”圈出来作为除数！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "对于单纯的人数增减题，直接把“人”等价于“效率 P”。人头数就是分母。"}]}]}$$ AS jsonb), NULL, '人数变化的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "人数变化"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_e_people", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
